INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('-4SWWa9JWDhvNeqQU8_0d','region-cn-shenzhen','大雁顶','dayanding','["hiking"]','published','深圳第三高峰',replace('大雁顶位于大鹏半岛七娘山系，海拔801米，是深圳第三高峰。山顶可俯瞰大鹏湾、排牙山等美景，是摄影爱好者的天堂。山势险峻，沿途风光壮丽，是户外挑战的绝佳选择。\n\n另有路线：鹿嘴山庄环线（适中/2-3h/5km）','\n',char(10)),'深圳市大鹏新区杨梅坑鹿嘴山庄',22.4789,114.5678,'https://cos.gomate.live/locations/hiking/dayan-peak/dayanding_01.jpg','["https://cos.gomate.live/locations/hiking/dayan-peak/dayanding_01.jpg"]','{"hiking":{"difficulty":"hard","duration_min":210,"duration_max":300,"distance_km":7,"elevation_gain_m":801,"best_seasons":["春季","秋季","冬季"],"overview":"从鹿嘴山庄出发，沿山脊步道攀登，途经多个观景平台，最终到达801米主峰。","tips":["建议早出发，避开正午高温","山顶风大，注意保暖","可顺路游览美人鱼拍摄地"],"warnings":["全程无补给","山路较陡","雷雨天气禁止登山"]},"facilities":["停车场","卫生间"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('2qbVa9QLOrl_Ty2DkxOqL','region-cn-lijiang','玉龙雪山','yulong-snow-mountain','["hiking"]','published','纳西神山','玉龙雪山是北半球最南的大雪山，主峰扇子陡海拔5596米，是纳西族人心中的神山。雪山以险、奇、美、秀著称，有冰川公园、蓝月谷、云杉坪等景点。乘坐大索道可直达海拔4506米的冰川公园，近距离感受雪山魅力。蓝月谷湖水湛蓝，被誉为「小九寨」。','云南省丽江市玉龙纳西族自治县',27.1008,100.1828,'https://cos.gomate.live/locations/hiking/yulong-snow-mountain/yulong_xueshan_01.jpg','["https://cos.gomate.live/locations/hiking/yulong-snow-mountain/yulong_xueshan_01.jpg","https://cos.gomate.live/locations/hiking/yulong-snow-mountain/yulong_xueshan_02.jpg"]','{"hiking":{"best_seasons":["春季","冬季"],"tips":["提前准备氧气瓶","注意高原反应","蓝月谷不容错过"],"warnings":["海拔高易高反","天气多变","需提前预订索道票"]},"facilities":["索道","观景台","氧气站","餐厅"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('3gg6eJC6wotvSqTKwneZ1','region-cn-shenzhen','壹方天地','yifang-tiandi','["leisure"]','published','龙华最大商业综合体','壹方天地是深圳龙华区最大的商业综合体，总建筑面积超过60万平方米，分为A、B、C、D四大主题商业区。这里汇集了国际时尚、潮流数码、餐饮美食、休闲娱乐等多种业态，是龙华区最热闹的社交聚集地。商场内设有IMAX影城、大型超市、儿童游乐中心等配套设施，是年轻人聚会、家庭休闲的理想场所。','深圳市龙华区人民路4022号',22.6543,114.0321,'https://images.unsplash.com/photo-1567449303078-57ad995bd17a?w=800&q=80','["https://images.unsplash.com/photo-1567449303078-57ad995bd17a?w=800&q=80","https://images.unsplash.com/photo-1519567241046-7f570eee3ce9?w=800&q=80","https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80","https://images.unsplash.com/photo-1555529669-e69e7aa0ba9a?w=800&q=80"]','{"facilities":["停车场","地铁站","电影院","超市","餐厅","咖啡厅","parking"]}',NULL,1772897870734,1775378951099);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('4KT7wxG41Lf1KJMcYbf_j','region-cn-shenzhen','大南山','dananshan','["hiking"]','published','俯瞰深圳湾',replace('大南山海拔336米，位于深圳南山区。山顶可俯瞰深圳湾、香港元朗、前海自贸区等美景，是观赏城市夜景的绝佳地点。交通便捷，是市民休闲健身的热门选择。\n\n另有路线：大南山海关登山道（轻松/1-1.5h/3.5km）','\n',char(10)),'深圳市南山区蛇口大南山',22.5123,113.9234,'https://cos.gomate.live/locations/hiking/danan-mountain/dananshan_01.jpg','["https://cos.gomate.live/locations/hiking/danan-mountain/dananshan_01.jpg","https://cos.gomate.live/locations/hiking/danan-mountain/dananshan_02.jpg"]','{"hiking":{"difficulty":"easy","duration_min":90,"duration_max":120,"distance_km":4,"elevation_gain_m":336,"best_seasons":["全年"],"overview":"从北山道入口出发，沿盘山公路上山，可俯瞰深圳湾和香港元朗美景。","tips":["傍晚可看日落","夜景非常美","交通便捷"],"warnings":["周末人流较多","夜间注意防滑"]},"facilities":["停车场","卫生间","自动售货机"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('4yQn7XN3Ls1sOQyHCW8Kf','region-cn-liuzhou','柳州市区','liuzhou-city','["explore"]','published','龙城壶城','柳州是广西最大的工业城市，也是一座有着2000多年历史的文化名城。柳江穿城而过，形成独特的「江流曲似九回肠」景观，市区宛如一个巨大的天然盆景，因此柳州又称「壶城」。柳州以螺蛳粉闻名全国，是吃货的天堂。此外，柳州的夜景也非常迷人，马鞍山上看夜景是必体验项目。','广西壮族自治区柳州市',24.3265,109.4285,'https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80','["https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80","https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&q=80","https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?w=800&q=80"]','{"facilities":["高铁站","机场","酒店","餐厅","水上巴士"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('6be910bc6b304f01a904e','region-cn-macau','澳门','macau','["leisure"]','published','周末城市漫游','澳门城市漫游，适合周末逛逛、看风景和体验城市文化。','澳门特别行政区',22.1987,113.5439,'https://images.unsplash.com/photo-1747582437136-1e97cd696703?auto=format&fit=crop&fm=jpg&q=80&w=1200','["https://images.unsplash.com/photo-1747582437136-1e97cd696703?auto=format&fit=crop&fm=jpg&q=80&w=1200"]','{}',NULL,1785940984000,1785941431000);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('79o2PRT0He1ndOjDkwhCf','region-cn-kunming','昆明西山','kunming-xishan','["hiking"]','published','滇中第一佳境',replace('昆明西山位于滇池西岸，海拔2507米，是昆明著名的风景名胜区。从西山远眺滇池，景色壮丽，素有''滇中第一佳境''之称。龙门石窟、华亭寺、太华寺等古迹点缀山间，是昆明市民周末徒步健身的热门去处。\n\n另有路线：西山全景穿越线（挑战/4-6h/8km）；西山索道上山徒步线（轻松/1.5-2.5h/2.5km）','\n',char(10)),'云南省昆明市西山区西山风景区',24.9567,102.6289,'https://cos.gomate.live/locations/hiking/xishan-kunming/kunming_xishan_01.jpg','["https://cos.gomate.live/locations/hiking/xishan-kunming/kunming_xishan_01.jpg","https://cos.gomate.live/locations/hiking/xishan-kunming/kunming_xishan_02.jpg","https://cos.gomate.live/locations/hiking/xishan-kunming/kunming_xishan_03.jpg","https://cos.gomate.live/locations/hiking/xishan-kunming/kunming_xishan_04.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":120,"duration_max":180,"distance_km":4.5,"elevation_gain_m":400,"best_seasons":["春季","秋季","冬季"],"overview":"从西山公园入口出发，经华亭寺、太华寺到达龙门石窟，可俯瞰滇池全景。","tips":["前半段较平缓","龙门石窟是精华","可乘坐环保车上山"],"warnings":["节假日人流较大"]},"facilities":["索道","停车场","卫生间","餐厅","观景台"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('a7a1bt-iWiTynIHoxpiLa','region-cn-pingxiang','武功山','wugong-mountain','["hiking"]','published','云中草原，户外天堂',replace('武功山位于江西省萍乡市，主峰白鹤峰（金顶）海拔1918.3米。以十万亩高山草甸、云海日出、星空露营闻名，被誉为''中国最美的高山草甸''，是户外爱好者和摄影爱好者的天堂。\n\n另有路线：武功山全程穿越（挑战/12-18h/20km）；武功山休闲索道路线（轻松/2-4h/3km）','\n',char(10)),'江西省萍乡市芦溪县武功山风景区',27.4567,114.1789,'https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_01.jpg','["https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_01.jpg","https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_02.jpg","https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_03.jpg","https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_04.jpg","https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_05.jpg","https://cos.gomate.live/locations/hiking/wugong-mountain/wugongshan_06.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":240,"duration_max":360,"distance_km":6,"elevation_gain_m":1400,"best_seasons":["春季","秋季"],"overview":"从武功山游客中心出发，可选择步行或索道上山，经好汉坡、吊马桩，最终到达金顶。","tips":["可选择索道上山节省体力","金顶可观日出云海","山顶有客栈和帐篷营地"],"warnings":["山顶风大温差大","注意防晒","旺季需提前订房"]},"facilities":["索道","客栈","营地","卫生间","餐厅"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('ALARwo1GBuwF-SuRV0mxJ','region-cn-shenzhen','阳台山','yangtai-mountain','["hiking"]','published','城市绿肺',replace('阳台山（原名羊台山）位于深圳市西北部，是深圳八景之一。主峰海拔587.3米，是深圳西部的最高峰。这里风景秀丽，森林覆盖率高，是市民休闲健身的好去处，也是深圳市重要的生态屏障。\n\n另有路线：大小阳台山穿越（适中/3-4h/8km）；阳台山大环线（挑战/4-6h/12km）','\n',char(10)),'深圳市宝安区石岩街道阳台山森林公园',22.6789,113.9654,'https://cos.gomate.live/locations/hiking/yangtai-mountain/yangtaishan_01.jpg','["https://cos.gomate.live/locations/hiking/yangtai-mountain/yangtaishan_01.jpg","https://cos.gomate.live/locations/hiking/yangtai-mountain/yangtaishan_02.jpg","https://cos.gomate.live/locations/hiking/yangtai-mountain/yangtaishan_03.jpg"]','{"hiking":{"difficulty":"easy","duration_min":90,"duration_max":150,"distance_km":4,"elevation_gain_m":587,"best_seasons":["全年"],"overview":"从阳台山森林公园石岩入口出发，沿台阶路直上山顶，沿途有多个休息平台和观景台。","tips":["台阶路为主，路况好","沿途有自动售货机","适合带老人小孩"],"warnings":["周末人流较多","台阶较多注意膝盖保护"]},"facilities":["停车场","卫生间","自动售货机","观景台"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('bbv3epGZWsZvHXCdN22Sx','region-cn-shenzhen','梅沙尖','meishajian','["hiking"]','published','360度观景平台',replace('梅沙尖海拔753米，是深圳第四高峰。山顶视野开阔，可360度俯瞰盐田港、大梅沙、梧桐山、七娘山等美景。山上常年云雾缭绕，如同仙境，是深圳不可多得的观景胜地。\n\n另有路线：三洲田线（适中/3-4h/6km）','\n',char(10)),'深圳市盐田区三洲田梅沙尖',22.6012,114.289,'https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_05.jpg','["https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_01.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_02.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_03.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_04.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_05.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_06.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_07.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_08.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_09.jpg","https://cos.gomate.live/locations/hiking/meisha-peak/meishajian_10.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":150,"duration_max":210,"distance_km":5,"elevation_gain_m":753,"best_seasons":["全年"],"overview":"从山海大观入口出发，沿山脊步道登顶，山顶可360度俯瞰深圳东部美景。","tips":["日出日落时分景色最美","建议带长焦镜头","山顶常年云雾缭绕"],"warnings":["部分路段为野路","无补给点","注意防滑"]},"facilities":["停车场"]}',NULL,1772897870733,1775288599249);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('cLM8j6iNSp59NvFyTdQtM','region-cn-dali','洱海','erhai-lake','["travel"]','published','高原明珠','洱海是云南省第二大淡水湖，因形状似人耳而得名。湖水清澈见底，四周群山环抱，风光旖旎。环洱海一周约130公里，沿途经过双廊、喜洲、挖色等古镇村落，是骑行和自驾的绝佳路线。洱海日出日落美不胜收，是摄影爱好者的天堂。','云南省大理白族自治州大理市洱海',25.7776,100.1864,'https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80','["https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80","https://images.unsplash.com/photo-1599577908906-8d6c700342b5?w=800&q=80","https://images.unsplash.com/photo-1527212986666-4d2d47a4d0cc?w=800&q=80"]','{"facilities":["环湖公路","观景台","码头","餐厅"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('CXy8k3dyyqX1peWk0Ubbs','region-cn-dali','大理','dali-old-town','["travel"]','published','风花雪月之地','大理古城位于云南省西部，是大理白族自治州的首府。古城始建于明洪武十五年，距今已有600多年历史。这里背靠苍山，面临洱海，四季如春，风景秀丽。古城内白族民居建筑独具特色，洋人街、人民路热闹非凡，是体验白族文化、品尝云南美食的绝佳去处。','云南省大理白族自治州大理市',25.6949,100.1661,'https://images.unsplash.com/photo-1470004914212-05527e49370b?w=800&q=80','["https://images.unsplash.com/photo-1470004914212-05527e49370b?w=800&q=80","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80","https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&q=80"]','{"facilities":["停车场","民宿","餐厅","酒吧","咖啡馆"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('D8hoyLNzfguafyyh10pKc','region-cn-kunming','昆明','kunming-city','["explore"]','published','春城','昆明是云南省省会，享有「春城」之美誉。这里气候温和，夏无酷暑，冬无严寒，四季如春。昆明历史悠久，文化底蕴深厚，是国务院公布的首批国家历史文化名城之一。作为西南重要的高原城市，昆明周边拥有滇池、西山等著名景点，是户外爱好者探索云南的绝佳起点。无论是漫步翠湖公园，还是品尝地道的过桥米线，昆明都能带给你独特的体验。','云南省昆明市',24.88149,102.833669,'https://cos.gomate.live/locations/city/kunming/kunming_01.jpg','["https://cos.gomate.live/locations/city/kunming/kunming_01.jpg","https://cos.gomate.live/locations/city/kunming/kunming_02.jpg"]','{}',NULL,1772897870734,1772899766);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('dsIPDpWeEZOQUzk0LJs8Q','region-cn-xishuangbanna','野象谷','wild-elephant-valley','["hiking"]','published','亚洲象家园','野象谷是中国唯一可以近距离观赏亚洲野象的地方，位于西双版纳国家级自然保护区内。景区内有高空观象栈道、大象学校、热带雨林等景点。游客可以通过高空栈道安全地观察野生亚洲象的活动，也可以在大象学校观看大象表演，了解大象的生活习性。','云南省西双版纳傣族自治州景洪市勐养镇',22.13,100.87,'https://images.unsplash.com/photo-1557050543-4d5f4e07ef46?w=800&q=80','["https://images.unsplash.com/photo-1557050543-4d5f4e07ef46?w=800&q=80","https://images.unsplash.com/photo-1547721067-5514263b857c?w=800&q=80","https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800&q=80"]','{"hiking":{"best_seasons":["冬季","春季"],"tips":["早上观象概率更高","大象表演有固定时间","建议提前到达"],"warnings":["观象需运气","保持安静","不要投喂动物"]},"facilities":["高空栈道","观景台","餐厅","大象学校"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('dYoJC0GnpzQznxDjmwR05','region-cn-shenzhen','Kuddo Coffee','kuddo-coffee','["leisure"]','published','精品咖啡空间','Kuddo Coffee 是一家源自深圳的精品咖啡品牌，以其简约的工业风设计和优质的咖啡出品受到年轻人的喜爱。位于壹方天地的门店空间宽敞明亮，提供舒适的休闲环境，是商务会谈、朋友聚会、安静办公的理想场所。店内提供手冲咖啡、意式咖啡、创意特调等多种选择，还有精致的甜点和简餐搭配。','深圳市龙华区人民路4022号壹方天地B区',22.6545,114.0323,'https://images.unsplash.com/photo-1554118811-1e0d58224f24?w=800&q=80','["https://images.unsplash.com/photo-1554118811-1e0d58224f24?w=800&q=80","https://images.unsplash.com/photo-1445116572660-236099ec97a0?w=800&q=80"]','{"facilities":["WiFi","插座","洗手间","无障碍设施"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('eRKwV8pnSN1c5h9Cnd2gU','region-cn-changsha','衡山','heng-mountain','["hiking"]','published','五岳之南岳',replace('衡山是中国五岳之一，位于湖南省衡阳市，主峰祝融峰海拔1300.2米。自古以''五岳独秀''、''文明奥区''著称，是著名的道教和佛教圣地，也是观日出、云海、雾凇的绝佳之地。\n\n另有路线：衡山古道朝圣线（适中/5-7h/10km）；衡山休闲索道路线（轻松/2-3h/3km）','\n',char(10)),'湖南省衡阳市南岳区衡山风景区',27.2567,112.6789,'https://cos.gomate.live/locations/hiking/hengshan-mountain/hengshan_01.jpg','["https://cos.gomate.live/locations/hiking/hengshan-mountain/hengshan_01.jpg","https://cos.gomate.live/locations/hiking/hengshan-mountain/hengshan_02.jpg","https://cos.gomate.live/locations/hiking/hengshan-mountain/hengshan_03.jpg","https://cos.gomate.live/locations/hiking/hengshan-mountain/hengshan_04.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":240,"duration_max":360,"distance_km":9,"elevation_gain_m":1100,"best_seasons":["春季","秋季","冬季"],"overview":"从南岳衡山游客中心出发，经康家垅门票处，沿登山步道经忠烈祠、穿岩诗林、南天门，最终到达祝融峰。","tips":["可乘观光车至半山亭节省体力","祝融峰是最佳观日出点","沿途有多处寺庙可参观"],"warnings":["山顶风大","冬季路面可能结冰","旺季人流较大"]},"facilities":["索道","观光车","客栈","餐厅","卫生间"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('FKIOkqhS1UAP0tpE7ddW1','region-cn-shenzhen','七娘山','qiniang-mountain','["hiking"]','published','深圳第二高峰',replace('七娘山位于大鹏半岛南岛，主峰海拔869米，是深圳第二高峰。山上七座山峰错落有致，山势险峻，山中森林茂盛，保存着未经人为破坏的常绿阔叶林。这里是户外爱好者的天堂，可以俯瞰大鹏半岛的壮丽海景。\n\n另有路线：七娘山科考线（适中/3-4h/6km）','\n',char(10)),'深圳市大鹏新区南澳街道七娘山',22.5289,114.5456,'https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_06.jpg','["https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_01.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_02.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_03.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_04.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_05.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_06.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_07.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_08.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_09.jpg","https://cos.gomate.live/locations/hiking/qiniang-mountain/qiniangshan_10.jpg"]','{"hiking":{"difficulty":"hard","duration_min":240,"duration_max":360,"distance_km":8,"elevation_gain_m":869,"best_seasons":["autumn","winter"],"overview":"从七娘山登山口出发，经一号峰至七号峰，最终到达主峰。全程山野路，需要一定户外经验。","tips":["建议早出发，带足水和食物","山顶风大，注意保暖","部分路段需要手脚并用"],"warnings":["全程无补给","雷雨天气禁止登山","建议结伴而行"]},"facilities":["停车场","登山入口标识"]}',NULL,1772897870733,1775288541322);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('Ha2v4QFa518e_geUuz9eC','region-cn-shenzhen','梧桐山','wutong-mountain','["hiking"]','published','深圳第一高峰',replace('梧桐山风景名胜区位于深圳东部，包括东湖公园、仙湖植物园、沙头角林场等，是国内少有的邻近市区、以滨海、山地和自然植被为景观主体的国家级风景名胜区。主峰大梧桐海拔943.7米，为深圳第一高峰。\n\n另有路线：好汉坡线路（挑战/1.5-2.5h/4km）；百年古道（轻松/2.5-3.5h/6.5km）','\n',char(10)),'深圳市罗湖区莲塘街道梧桐山风景区',22.5964,114.2185,'https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_01.jpg','["https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_01.jpg","https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_02.jpg","https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_03.jpg","https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_04.jpg","https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_05.jpg","https://cos.gomate.live/locations/hiking/wutong-mountain/wutongshan_06.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":120,"duration_max":180,"distance_km":5.5,"elevation_gain_m":700,"best_seasons":["春季","秋季"],"overview":"从梧桐山村出发，沿泰山涧步道上山，途经多个观景点，最终到达大梧桐山顶。全程石阶路，路况良好。","tips":["前半段平缓，后半段较陡","沿途有多个休息点","山顶有小卖部可补给"],"warnings":["周末人流较多","雨天路滑注意安全"]},"facilities":["停车场","卫生间","小卖部","观景台"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('hgIQruWnKPMJN-kq0YMGF','region-cn-shenzhen','莲花山','lianhuashan','["hiking"]','published','市中心绿肺',replace('莲花山海拔106米，位于深圳市中心区。山顶有邓小平铜像，可俯瞰整个福田中心区，是市民休闲健身的热门场所。地势平缓，适合老人小孩，也是放风筝的好地方。\n\n另有路线：莲花山环湖线（轻松/0.8-1.3h/3km）','\n',char(10)),'深圳市福田区莲花山森林公园',22.5534,114.0567,'https://cos.gomate.live/locations/hiking/lianhua-mountain/lianhuashan_01.jpeg','["https://cos.gomate.live/locations/hiking/lianhua-mountain/lianhuashan_01.jpeg"]','{"hiking":{"difficulty":"easy","duration_min":30,"duration_max":60,"distance_km":2,"elevation_gain_m":106,"best_seasons":["全年"],"overview":"从南门入口出发，沿缓坡步道轻松登顶，参观邓小平铜像和山顶广场。","tips":["地势平缓，适合老人小孩","山顶可俯瞰福田CBD","风筝广场可放风筝"],"warnings":["节假日人流量极大","注意保管随身物品"]},"facilities":["停车场","卫生间","小卖部","餐厅"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('HHRbfx9P9JUXmmB49Azy2','region-cn-changsha','长沙','changsha-city','["explore"]','published','星城','长沙是湖南省省会，古称潭州，别名「星城」，是首批国家历史文化名城。这里既有「岳麓山、湘江水、橘子洲」的自然风光，又有深厚的湖湘文化底蕴。作为一座充满活力的现代都市，长沙以美食闻名全国，臭豆腐、口味虾、糖油粑粑等特色小吃让人流连忘返。同时，长沙也是一座娱乐之都，夜生活丰富多彩，是年轻人聚会游玩的理想目的地。','湖南省长沙市',28.228304,112.938882,'https://cos.gomate.live/locations/city/changsha/changsha_04.jpg','["https://cos.gomate.live/locations/city/changsha/changsha_01.jpg","https://cos.gomate.live/locations/city/changsha/changsha_02.jpg","https://cos.gomate.live/locations/city/changsha/changsha_03.jpg","https://cos.gomate.live/locations/city/changsha/changsha_04.jpg","https://cos.gomate.live/locations/city/changsha/changsha_05.jpg","https://cos.gomate.live/locations/city/changsha/changsha_06.jpg","https://cos.gomate.live/locations/city/changsha/changsha_07.jpg"]','{}',NULL,1772897870734,1775293428659);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('hIII9tvuz9RqEIJe6HoK0','region-cn-xishuangbanna','景洪市区','jinghong-city','["explore"]','published','热带风情之都','景洪是西双版纳傣族自治州的首府，位于澜沧江畔，是一座充满热带风情的边境城市。这里有浓郁的傣族风情，金碧辉煌的佛寺，热闹的夜市，以及独特的热带水果。告庄西双景是网红打卡地，夜晚的星光夜市璀璨夺目，是体验傣族文化和品尝美食的好去处。','云南省西双版纳傣族自治州景洪市',22.0073,100.7978,'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80','["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80","https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80","https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?w=800&q=80"]','{"facilities":["机场","酒店","夜市","餐厅","佛寺"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('ilSMitTXZ2PmmbqJTNtIR','region-cn-lijiang','泸沽湖','lugu-lake','["travel"]','published','高原女儿国','泸沽湖位于云南与四川交界处，是中国第三大深水湖泊。湖水清澈蔚蓝，四周青山环抱，湖中有里务比岛、媳娃娥岛等岛屿。这里是摩梭人的故乡，保留着母系氏族社会的传统，被称为「女儿国」。环湖有里格半岛、情人滩、草海走婚桥等景点。','云南省丽江市宁蒗彝族自治县泸沽湖',27.7093,100.7787,'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&q=80','["https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&q=80","https://images.unsplash.com/photo-1439066615861-d1af74d74000?w=800&q=80","https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80"]','{"facilities":["环湖公路","观景台","码头","客栈"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('MCpSM2OFiwnD17em5Oxvg','region-cn-shenzhen','凤凰山','fenghuangshan','["hiking"]','published','宝安第一山',replace('凤凰山海拔376米，被誉为宝安第一山。山上有凤岩古庙，是深圳著名的祈福圣地，也是休闲徒步的好去处。山势平缓，适合全家老少一同登山。\n\n另有路线：凤凰山大环线（轻松/1.5-2.5h/5km）','\n',char(10)),'深圳市宝安区福永街道凤凰山森林公园',22.7123,113.8567,'https://cos.gomate.live/locations/hiking/fenghuang-mountain/fenghuangshan_01.jpeg','["https://cos.gomate.live/locations/hiking/fenghuang-mountain/fenghuangshan_01.jpeg"]','{"hiking":{"difficulty":"easy","duration_min":60,"duration_max":90,"distance_km":3,"elevation_gain_m":376,"best_seasons":["全年"],"overview":"从凤凰山森林公园入口出发，沿石阶路经凤岩古庙，最终到达山顶观景台。","tips":["古庙可烧香祈福","山路较缓，适合全家","周末人流较多"],"warnings":["古庙人多时注意财物","部分台阶较陡"]},"facilities":["停车场","卫生间","小卖部","餐厅"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('MMET9RdCtlXHRmfKmzLkM','region-cn-shenzhen','牛奶排','niunaipai','["hiking"]','published','深圳最难海岸线',replace('牛奶排位于大鹏半岛最南端，是深圳难度最高的海岸线穿越路线。需要攀爬、绳降、泅渡等多种技能，被誉为深圳户外毕业线路。风景绝美但难度极高，仅限经验丰富的户外达人挑战。\n\n另有路线：牛奶排休闲观光线（适中/2-3h/3km）','\n',char(10)),'深圳市大鹏新区西涌牛奶排',22.4234,114.5012,'https://cos.gomate.live/locations/hiking/niunai-cape/nainiupai_01.jpg','["https://cos.gomate.live/locations/hiking/niunai-cape/nainiupai_01.jpg","https://cos.gomate.live/locations/hiking/niunai-cape/nainiupai_02.jpg","https://cos.gomate.live/locations/hiking/niunai-cape/nainiupai_03.jpg","https://cos.gomate.live/locations/hiking/niunai-cape/nainiupai_04.jpg"]','{"hiking":{"difficulty":"expert","duration_min":300,"duration_max":480,"distance_km":5,"elevation_gain_m":200,"best_seasons":["秋季","冬季"],"overview":"从西涌出发，沿海岸线穿越牛奶排，途经多个需要绳索下降的断崖和泅渡点，最终到达磨刀坑。","tips":["必须结伴而行，不建议 solo","携带专业装备（绳索、安全带等）","提前了解潮汐，选择退潮时段"],"warnings":["难度极高，新手勿入","需要专业装备","注意潮汐变化","建议结伴而行","风险自负"]},"facilities":["停车场"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('PLBLsohhxp0ZVnx6rIRpw','region-cn-shenzhen','马峦山','maluan-mountain','["hiking"]','published','深圳最大瀑布群',replace('马峦山位于深圳市东部山区，有深圳最大的瀑布群。这里谷深林茂，溪流潺潺，空气清新，是远离城市喧嚣的好去处。马峦山徒步路线平缓，适合各年龄段的户外爱好者，尤其是夏季避暑纳凉的好地方。\n\n另有路线：马峦山大环线（适中/4-5h/10km）','\n',char(10)),'深圳市坪山区马峦街道马峦山郊野公园',22.6456,114.3456,'https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_01.jpg','["https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_01.jpg","https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_02.jpg","https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_03.jpg","https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_04.jpg","https://cos.gomate.live/locations/hiking/maluan-mountain/maluanshan_05.jpg"]','{"hiking":{"difficulty":"easy","duration_min":120,"duration_max":180,"distance_km":6,"elevation_gain_m":400,"best_seasons":["夏季","秋季"],"overview":"从小梅沙或坪山入口出发，沿溪谷步道前行，途经多个瀑布点，最终到达大瀑布。","tips":["雨季瀑布更壮观","可在马峦山村吃农家菜","路况平缓，适合亲子"],"warnings":["雨后路滑注意安全","溪边玩耍注意安全","保护环境勿乱丢垃圾"]},"facilities":["停车场","农家乐","卫生间"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('PWmMptGDplEKnETrRFT4f','region-cn-dali','苍山','cangshan-mountain','["hiking"]','published','云岭之颠','苍山又名点苍山，是大理的天然屏障，有十九峰十八溪之说。主峰马龙峰海拔4122米，山顶终年积雪。苍山景色以雪、云、石著称，是大理「风花雪月」四景之一。乘坐洗马潭索道可直达山顶，俯瞰洱海全景。山中还有著名的感通寺、寂照庵等古刹。','云南省大理白族自治州大理市苍山',25.6856,100.1065,'https://cos.gomate.live/locations/hiking/cangshan-mountain/cangshan_01.jpg','["https://cos.gomate.live/locations/hiking/cangshan-mountain/cangshan_01.jpg","https://cos.gomate.live/locations/hiking/cangshan-mountain/cangshan_02.jpg","https://cos.gomate.live/locations/hiking/cangshan-mountain/cangshan_03.jpg"]','{"hiking":{"best_seasons":["春季","夏季","秋季"],"tips":["建议乘坐索道上山","山顶气温低需带外套","寂照庵素斋有名"],"warnings":["高原反应需注意","天气变化快"]},"facilities":["索道","观景台","休息站"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('QLSI8E6N25L2-HqkR0IcQ','region-cn-chengdu','成都','chengdu-city','["explore"]','published','天府之国','成都是四川省省会，素有「天府之国」的美誉。这座有着4500年文明史的历史文化名城，是中国西南地区的经济、文化中心。成都以悠闲的生活方式闻名，茶馆文化、川剧变脸、火锅美食构成了独特的城市气质。作为大熊猫的故乡，成都拥有全球知名的大熊猫繁育研究基地。此外，成都周边青城山、都江堰、西岭雪山等景点众多，是探索四川自然风光的绝佳起点。','四川省成都市',30.5728,104.0668,'https://cos.gomate.live/locations/city/chengdu/chengdu_01.jpg','["https://cos.gomate.live/locations/city/chengdu/chengdu_01.jpg"]','{"facilities":["地铁","公交","出租车","共享单车","高铁站","机场"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('s45uNzx_imcithzvJxDKA','region-cn-huizhou','大南山','huizhou-dananshan','["hiking"]','published','粤东第一峰','大南山位于惠州市惠东县，是粤东地区最高峰，海拔1105米。山势雄伟，自然风光秀丽，是徒步爱好者的热门目的地。山顶视野开阔，可俯瞰整个惠东平原，天气晴朗时甚至可以看到远处的海岸线。','惠州市惠东县大南山',22.9833,114.9833,'https://gomate.cos.jiahongw.com/locations/1775623899746.jpeg','["https://gomate.cos.jiahongw.com/locations/1775623899746.jpeg","https://gomate.cos.jiahongw.com/locations/1775625693616.jpeg","https://gomate.cos.jiahongw.com/locations/1775625696830.jpeg"]','{"hiking":{"best_seasons":["spring","autumn","winter"]}}',NULL,1775538430925,1775625701953);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('SIeh5mO-kGWYVP-qyQ0bx','region-cn-xishuangbanna','中科院植物园','xtbg','["travel"]','published','植物王国','中国科学院西双版纳热带植物园是中国最大、物种最丰富的热带植物园，也是国家5A级旅游景区。园区占地1100公顷，收集了13000多种热带植物，有王莲池、棕榈园、奇花异卉园等特色园区。这里是植物爱好者的天堂，也是了解热带雨林生态系统的绝佳场所。','云南省西双版纳傣族自治州勐腊县勐仑镇',21.93,101.25,'https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?w=800&q=80','["https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?w=800&q=80","https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=800&q=80","https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800&q=80"]','{"facilities":["游览车","餐厅","讲解员","纪念品店"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('SWM825N0bXnuhRChczfNQ','region-cn-lijiang','丽江古城','lijiang-old-town','["travel"]','published','东方威尼斯','丽江古城又名大研古城，是中国历史文化名城之一，也是世界文化遗产。古城始建于宋末元初，距今已有800多年历史。城内街道依山傍水修建，以红色角砾岩铺就，有四方街、木府、五凤楼等景点。古城水系发达，小桥流水人家，被誉为「东方威尼斯」。','云南省丽江市古城区',26.8721,100.2296,'https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80','["https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80","https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&q=80"]','{"facilities":["停车场","民宿","餐厅","酒吧","咖啡馆"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('TAL5nwPsO3Csw8mnaPP4C','region-cn-shenzhen','深圳','shenzhen-city','["explore"]','published','创新之都','深圳是中国改革开放的前沿城市，从一个小渔村发展成为国际化大都市。这里不仅有繁华的都市景观、现代化的建筑群，还有丰富的自然资源。深圳拥有众多山体公园和海岸线，如梧桐山、七娘山、东西涌等，是户外爱好者的天堂。同时，深圳也是一座充满活力的创新之城，汇集了来自全国各地的年轻人，夜生活丰富多彩，美食文化多元包容。','广东省深圳市',22.5431,114.0579,'https://cos.gomate.live/locations/city/shenzhen/shenzhen_06.jpg','["https://cos.gomate.live/locations/city/shenzhen/shenzhen_01.jpg","https://cos.gomate.live/locations/city/shenzhen/shenzhen_02.jpg","https://cos.gomate.live/locations/city/shenzhen/shenzhen_03.jpg","https://cos.gomate.live/locations/city/shenzhen/shenzhen_04.jpg","https://cos.gomate.live/locations/city/shenzhen/shenzhen_05.jpg","https://cos.gomate.live/locations/city/shenzhen/shenzhen_06.jpg"]','{"facilities":["地铁","公交","出租车","共享单车","高铁站","机场"]}',NULL,1772897870734,1775293471791);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('TCx0S_SREyl-wARMAlvhr','region-cn-shenzhen','大笔架山','dabijiashan','["hiking"]','published','深圳十峰之一',replace('大笔架山位于深圳与惠州交界处，海拔717米，是深圳十峰之一。山势起伏，是深圳经典的三水线的重要组成部分。这里原始生态保持完好，是户外爱好者的挑战圣地。\n\n另有路线：大笔架山环线（适中/3-4h/6km）','\n',char(10)),'深圳市龙岗区葵涌街道大笔架山',22.6456,114.4123,'https://cos.gomate.live/locations/hiking/dabijia-mountain/dabijiashan_01.jpg','["https://cos.gomate.live/locations/hiking/dabijia-mountain/dabijiashan_01.jpg"]','{"hiking":{"difficulty":"hard","duration_min":240,"duration_max":360,"distance_km":8,"elevation_gain_m":717,"best_seasons":["秋季","冬季","春季"],"overview":"从葵涌出发，经大笔架山主峰，体验深圳最经典的山脊穿越路线之一。","tips":["需要较好体能","建议早出发","带足水和食物"],"warnings":["路线较长","全程无补给","需要一定户外经验"]},"facilities":["停车场"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('VG_eTzdrxfy6o9vWQsMtI','region-cn-shenzhen','东西涌','dongxichong','["hiking"]','published','中国最美八大海岸线之一',replace('东西涌海岸线位于大鹏半岛，是中国最美丽的八大海岸线之一，也是深圳最经典的海岸徒步线路。东涌到西涌的穿越路线全长约6公里，沿途可以欣赏到壮观的海蚀地貌、奇特的海岸礁石和清澈的海水。\n\n另有路线：东涌环线（轻松/1.5-2.5h/4km）','\n',char(10)),'深圳市大鹏新区南澳街道东涌/西涌',22.4765,114.5689,'https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_04.jpg','["https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_01.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_02.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_03.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_04.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_05.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_06.jpg","https://cos.gomate.live/locations/hiking/dongxi-coast/dongxiyong_07.jpg"]','{"hiking":{"difficulty":"moderate","duration_min":180,"duration_max":300,"distance_km":6,"elevation_gain_m":200,"best_seasons":["spring","autumn"],"overview":"从东涌沙滩出发，沿海岸线礁石向西涌方向穿越，中途需翻越5个山头，部分路段需要攀爬。","tips":["穿防滑鞋，带手套","提前查询潮汐时间","带足饮用水（至少2L）"],"warnings":["注意潮汐变化","部分路段需要在礁石上攀爬","建议结伴而行"]},"facilities":["停车场","农家乐","卫生间"]}',NULL,1772897870733,1775288566493);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('vnm0CJd4QMfFY6w2MLJFo','region-cn-hong-kong','麦理浩径','maclehose-trail','["hiking"]','published','香港最美徒步径',replace('麦理浩径是香港最长的远足径，全长100公里，共分10段。横跨香港新界东西，途经八个郊野公园，沿途风景壮丽，包括万宜水库、大浪湾、狮子山等著名景点，被誉为全球最佳徒步径之一。\n\n另有路线：麦理浩径第二段（适中/4-6h/13.5km）；麦理浩径一二段连穿（挑战/7-10h/24km）','\n',char(10)),'香港新界西贡北潭涌至屯门',22.3964,114.1095,'https://cos.gomate.live/locations/hiking/maclehose-trail/mailihaojing_01.jpg','["https://cos.gomate.live/locations/hiking/maclehose-trail/mailihaojing_01.jpg"]','{"hiking":{"difficulty":"easy","duration_min":120,"duration_max":180,"distance_km":10.6,"elevation_gain_m":150,"best_seasons":["秋季","冬季","春季"],"overview":"从北潭涌出发，沿万宜水库步行至东坝，欣赏世界地质公园的独特地貌，最终到达浪茄沙滩。","tips":["路况平坦，适合新手","东坝风景绝美，多拍照","浪茄沙滩可露营"],"warnings":["全程无遮阴，注意防晒","夏季炎热"]},"facilities":["营地","卫生间","补给点","公交站"]}',NULL,1772897870733,1772897870733);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('ZBrIRJlTs-dl_7Oti6g7X','region-cn-liuzhou','三江程阳八寨','chengyang-bazhai','["travel"]','published','侗族风情','程阳八寨位于柳州三江县，是侗族聚居的八个自然村寨的统称。这里有世界四大名桥之一的程阳永济风雨桥，始建于1912年，是侗族建筑艺术的杰出代表。八个寨子依山傍水，吊脚楼鳞次栉比，鼓楼巍峨耸立，是体验侗族文化、欣赏侗族建筑、聆听侗族大歌的绝佳去处。','广西壮族自治区柳州市三江侗族自治县林溪镇',25.8985,109.5858,'https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=800&q=80','["https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=800&q=80","https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80","https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80"]','{"facilities":["民宿","餐厅","观景台","风雨桥"]}',NULL,1772897870734,1772897870734);
INSERT INTO "locations" ("id","region_id","name","slug","supported_activity_types","status","subtitle","description","address","latitude","longitude","cover_image_url","images","extra","created_by_user_id","created_at","updated_at") VALUES('ZytggMdDtsdOiX5NeT5zD','region-cn-hong-kong','香港','hongkong-city','["explore"]','published','东方之珠','香港是中华人民共和国特别行政区，被誉为「东方之珠」。这座国际大都会融合了东西方文化，既有繁华的都市景观，又有迷人的自然风光。维多利亚港的璀璨夜景、中环的摩天大楼、尖沙咀的购物天堂，以及遍布全港的郊野公园和徒步径，让香港成为一座动静皆宜的魅力之城。无论是品味地道港式茶餐厅美食，还是探索离岛风情，香港都能带给你独特的体验。','香港特别行政区',22.3193,114.1694,'https://cos.gomate.live/locations/city/hongkong/xianggang_01.jpg','["https://cos.gomate.live/locations/city/hongkong/xianggang_01.jpg"]','{}',NULL,1772897870734,1772904060);
